import { env } from './env';
import { adminUrl, apiUrl, appUrl, marketingUrl } from './urls';

// ---------- HELPERS ----------
/** Determine which stage (environment the app is running in) */
const stage =
  // The backend uses env?.STAGE (generated by sst)
  env?.STAGE ||
  // The frontend (deployed) uses NEXT_PUBLIC_STAGE (set inside website stack)
  process.env.NEXT_PUBLIC_STAGE;

/** Whether we're running against production resources */
let isProd = false;
// Prod should both use prod resources
if (stage === 'prod' || stage === 'staging') {
  isProd = true;
}

/** Whether this application is running as one of our main deployments (not locally) */
const isDeployment = ['prod', 'dev'].includes(stage ?? '');

// ---------- MAIN CONFIG ----------
/** The configuration object that defines global settings for the app */
export const config = {
  /** The overall stage the application is running in */
  stage,
  /** Whether this application is running as one of our main deployments (not locally) */
  isDeployment,
  /** Whether this application has a custom domain configured */
  hasCustomDomain: !apiUrl.includes('amazonaws.com'),
  /** Whether we're running in an AWS deployment */
  isAWS: !!(process?.env?.LAMBDA_TASK_ROOT || process?.env?.AWS_EXECUTION_ENV),
  /** Whether the application is using production resources */
  isProd,
  /** Some details regarding the project */
  app: {
    /** The name of the project */
    name: 'My App',
    /** The url of the project */
    url: appUrl,
    /** The inbox that receives contact form submissions */
    supportEmail: '',
  },
  /** Details for our backend API */
  api: {
    /** The URL of our own API */
    url: apiUrl,
  },
  /** Details for our admin dashboard */
  admin: {
    /** The URL of the admin dashboard */
    url: adminUrl,
  },
  /** Details for our marketing site */
  marketing: {
    /** The URL of the marketing site */
    url: marketingUrl,
  },
  /** The configuration for PostHog (our analytics, error tracking, logs, and email system) */
  posthog: {
    /** The PostHog project ID */
    projectId: isProd ? '171114' : '171115',
    /** Analytics, error tracking, and logs */
    analytics: {
      /** Whether analytics is enabled */
      isEnabled: isDeployment,
      /** The PostHog project API key */
      apiKey: isProd
        ? 'phc_LE5qHtqyJtBrzG4vRkfTY5OKmc3bBhEf7u8OEPyneCD'
        : 'phc_xKfOXqc9QAqX5E1KIepSG9EcG2FddQWvupGTvogQ0AH',
    },
    /** Transactional emails */
    email: {
      /** The transactional email template IDs */
      templates: {
        /** Sent when a user asks to reset their password */
        resetPassword: isProd ? '' : '01a16682-3704-0000-b61e-b31c5104117c',
        /** Sent to the support inbox for contact form submissions */
        contactFormSubmission: isProd ? '' : '01a16683-067a-0000-a15f-1c0dd04c6663',
        /** Sent when a user is invited to an organization */
        inviteToOrganization: isProd ? '' : '01a16e2b-5adc-0000-53f9-4e3620450d1c',
      },
    },
  },
  /** The configuration for crisp (our chat system) */
  crisp: {
    /** The crisp chat website ID */
    websiteId: '',
  },
  /** The configuration for Stripe (our payment system) */
  stripe: (() => {
    const publishableKey = isProd ? '' : '';

    return {
      /** The Stripe publishable key */
      publishableKey,
      /** Whether Stripe is configured — true when publishableKey is set */
      isEnabled: !!publishableKey,
    };
  })(),
};
